typedef esp_gcm_context mbedtls_gcm_context;
static inline void mbedtls_gcm_init(mbedtls_gcm_context *ctx) { esp_aes_gcm_init(ctx); }
static inline void mbedtls_gcm_free(mbedtls_gcm_context *ctx) { esp_aes_gcm_free(ctx); }
static inline int mbedtls_gcm_setkey(mbedtls_gcm_context *ctx, int cipher, const unsigned char *key, unsigned int keybits) { return esp_aes_gcm_setkey(ctx, cipher, key, keybits); }
static inline int mbedtls_gcm_crypt_and_tag(mbedtls_gcm_context *ctx, int mode, size_t length, const unsigned char *iv, size_t iv_len, const unsigned char *add, size_t add_len, const unsigned char *input, unsigned char *output, size_t tag_len, unsigned char *tag) {
    int rc = esp_aes_gcm_starts(ctx, mode, iv, iv_len);
    if (rc != 0) return rc;
    if (add_len) {
        rc = esp_aes_gcm_update_ad(ctx, add, add_len);
        if (rc != 0) return rc;
    }
    size_t out_len = 0;
    rc = esp_aes_gcm_update(ctx, input, length, output, length, &out_len);
    if (rc != 0) return rc;
    size_t fin_len = 0;
    rc = esp_aes_gcm_finish(ctx, output ? (output + out_len) : NULL, 0, &fin_len, tag, tag_len);
    return rc;
}
static inline int mbedtls_gcm_auth_decrypt(mbedtls_gcm_context *ctx, size_t length, const unsigned char *iv, size_t iv_len, const unsigned char *add, size_t add_len, const unsigned char *tag, size_t tag_len, const unsigned char *input, unsigned char *output) {
    int rc = esp_aes_gcm_starts(ctx, MBEDTLS_GCM_DECRYPT, iv, iv_len);
    if (rc != 0) return rc;
    if (add_len) {
        rc = esp_aes_gcm_update_ad(ctx, add, add_len);
        if (rc != 0) return rc;
    }
    size_t out_len = 0;
    rc = esp_aes_gcm_update(ctx, input, length, output, length, &out_len);
    if (rc != 0) return rc;
    size_t fin_len = 0;
    rc = esp_aes_gcm_finish(ctx, NULL, 0, &fin_len, (unsigned char *)tag, tag_len);
    return rc;
}
