static inline const char *k_kernel_idf_root(void) {
    const char *e = getenv("IDF_PATH");
    return (e && e[0]) ? e : KERNEL_ESP_IDF_ROOT;
}
static inline const char *k_kernel_idf_components(void) {
    const char *e = getenv("IDF_PATH");
    if (e && e[0]) {
        static char path[PATH_MAX];
        const char *suffix = "/components";
        size_t need = strlen(e) + strlen(suffix) + 1;
        if (need <= sizeof(path)) {
            memcpy(path, e, strlen(e));
            memcpy(path + strlen(e), suffix, strlen(suffix) + 1);
            return path;
        }
    }
    return KERNEL_ESP_IDF_COMPONENTS;
}

