static long sys_bind_impl(uint32_t fd, uint32_t addr_u, uint32_t alen,
                           uint32_t,uint32_t,uint32_t) {
    struct task_struct *t=current; if (!t) return -EINTR;
    struct sockaddr_storage sa; if (alen>sizeof(sa)) return -EINVAL;
    copy_from_user(&t->cpu_ctx,&sa,addr_u,alen);
    return kernel_bind((int)fd,(struct sockaddr*)&sa,(socklen_t)alen);
}
static long sys_connect_impl(uint32_t fd, uint32_t addr_u, uint32_t alen,
                              uint32_t,uint32_t,uint32_t) {
    struct task_struct *t=current; if (!t) return -EINTR;
    struct sockaddr_storage sa; if (alen>sizeof(sa)) return -EINVAL;
    copy_from_user(&t->cpu_ctx,&sa,addr_u,alen);
    return kernel_connect((int)fd,(struct sockaddr*)&sa,(socklen_t)alen);
}
static long sys_listen_impl(uint32_t fd, uint32_t backlog,
                             uint32_t,uint32_t,uint32_t,uint32_t) {
    return kernel_listen((int)fd,(int)backlog);
}
static long sys_accept_impl(uint32_t fd, uint32_t addr_u, uint32_t alen_u,
                             uint32_t,uint32_t,uint32_t) {
    struct task_struct *t=current; if (!t) return -EINTR;
    struct sockaddr_storage sa; socklen_t alen=sizeof(sa);
    int r=kernel_accept((int)fd,(struct sockaddr*)&sa,&alen);
    if (r>=0&&addr_u) {
        copy_to_user(&t->cpu_ctx,addr_u,&sa,alen);
        put_user_u32(&t->cpu_ctx,alen_u,(uint32_t)alen);
    }
    return r;
}
static long sys_pipe_impl(uint32_t fds_u, uint32_t,uint32_t,uint32_t,uint32_t,uint32_t) {
    struct task_struct *t=current; if (!t) return -EINTR;
    int fds[2]; int r=do_pipe(fds);
    if (r==0) copy_to_user(&t->cpu_ctx,fds_u,fds,sizeof(fds));
    return r;
}
static long sys_epoll_create_impl(uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t) {
    struct task_struct *t=current; if (!t) return -EINTR;
    epoll_inst_t *ep=epoll_create_inst(); if (!ep) return -EMFILE;
    int fd=fd_alloc(t); if (fd<0) { ep->used=false; return fd; }

    struct file *f = file_alloc();
    if (!f) {
        fd_free(t, fd);
        ep->used = false;
        return -EMFILE;
    }
    f->inode = NULL;
    f->dentry = NULL;
    f->f_ops  = &epoll_file_ops;
    f->pos    = 0;
    f->flags  = 0;
    f->priv   = ep;
    t->fd_table[fd] = f;
    return fd;
}
static long sys_bpf_impl(uint32_t cmd, uint32_t attr_u, uint32_t size,
                          uint32_t,uint32_t,uint32_t) {
    struct task_struct *t=current; if (!t) return -EINTR;
    uint8_t attr[256];
    if (size > sizeof(attr)) return -E2BIG;
    if (size && copy_from_user(&t->cpu_ctx, attr, attr_u, size) < 0) return -EFAULT;
    switch (cmd) {
    case 0: { /* BPF_MAP_CREATE */
        if (size < 12u) return -EINVAL;
        uint32_t type, ksz, vsz;
        memcpy(&type, attr + 0, 4);
        memcpy(&ksz,  attr + 4, 4);
        memcpy(&vsz,  attr + 8, 4);
        bpf_map_t *m = bpf_map_create(type, ksz, vsz);
        if (!m) return -ENOMEM;
        int fd = fd_alloc(t); if (fd < 0) return fd;
        t->fd_table[fd] = m;
        return fd;
    }
    case 5: { /* BPF_PROG_LOAD */
        if (size < 8u) return -EINVAL;
        uint32_t insn_cnt_u32; uint32_t insns_u;
        memcpy(&insn_cnt_u32, attr + 0, 4);
        memcpy(&insns_u, attr + 4, 4);
        if (insn_cnt_u32 == 0 || insn_cnt_u32 > MAX_BPF_INSN) return -EINVAL;
        bpf_insn_t insns[MAX_BPF_INSN];
        if (copy_from_user(&t->cpu_ctx, insns, insns_u, insn_cnt_u32 * sizeof(bpf_insn_t)) < 0) return -EFAULT;
        bpf_prog_t *prog = NULL;
        k_spin_lock(&g_obj_lock);
        for (uint32_t i = 0; i < MAX_BPF_PROGS; ++i) if (!g_bpf_progs[i].used) { prog = &g_bpf_progs[i]; break; }
        if (!prog) { k_spin_unlock(&g_obj_lock); return -ENOSPC; }
        prog->used = true;
        k_spin_unlock(&g_obj_lock);
        int rc = bpf_prog_load(prog, insns, (uint16_t)insn_cnt_u32, "user_bpf");
        if (rc < 0) { k_spin_lock(&g_obj_lock); prog->used = false; k_spin_unlock(&g_obj_lock); return rc; }
        int fd = fd_alloc(t); if (fd < 0) { k_spin_lock(&g_obj_lock); prog->used = false; k_spin_unlock(&g_obj_lock); return fd; }
        t->fd_table[fd] = prog;
        return fd;
    }
    case 9: { /* BPF_PROG_ATTACH */
        if (size < 8u) return -EINVAL;
        uint32_t hook_u32, fd_u32;
        memcpy(&hook_u32, attr + 0, 4);
        memcpy(&fd_u32,   attr + 4, 4);
        if (hook_u32 >= BPF_HOOK_MAX) return -EINVAL;
        if (!fd_valid(t, (int)fd_u32)) return -EBADF;
        bpf_prog_t *prog = (bpf_prog_t *)t->fd_table[fd_u32];
        if (!prog || !prog->used) return -EINVAL;
        bpf_attach((bpf_hook_t)hook_u32, prog);
        return 0;
    }
    default:
        return -EINVAL;
    }
}
