static long sys_execve_impl(uint32_t path_u, uint32_t argv_u, uint32_t envp_u, uint32_t, uint32_t, uint32_t) {
    struct task_struct *t = current; if (!t) return -EINTR;
    char path[128];
    int n = strncpy_from_user(&t->cpu_ctx, path, path_u, sizeof(path));
    if (n < 0) return n;

    enum { K_EXEC_MAX_ARGS = 16, K_EXEC_MAX_ENVS = 16, K_EXEC_ARG_LEN = 96 };
    char argv_storage[K_EXEC_MAX_ARGS][K_EXEC_ARG_LEN];
    char *argv_local[K_EXEC_MAX_ARGS + 1];
    memset(argv_storage, 0, sizeof(argv_storage));
    memset(argv_local, 0, sizeof(argv_local));

    int argc = 0;
    if (argv_u) {
        for (; argc < K_EXEC_MAX_ARGS; ++argc) {
            uint32_t argp = 0;
            if (copy_from_user(&t->cpu_ctx, &argp, argv_u + (uint32_t)(argc * sizeof(uint32_t)), sizeof(argp)) < 0) break;
            if (!argp) break;
            if (strncpy_from_user(&t->cpu_ctx, argv_storage[argc], argp, sizeof(argv_storage[argc])) < 0) break;
            argv_local[argc] = argv_storage[argc];
        }
    }
    argv_local[argc] = NULL;

    char env_storage[K_EXEC_MAX_ENVS][K_EXEC_ARG_LEN];
    char *env_local[K_EXEC_MAX_ENVS + 1];
    memset(env_storage, 0, sizeof(env_storage));
    memset(env_local, 0, sizeof(env_local));
    int envc = 0;
    if (envp_u) {
        for (; envc < K_EXEC_MAX_ENVS; ++envc) {
            uint32_t envp = 0;
            if (copy_from_user(&t->cpu_ctx, &envp, envp_u + (uint32_t)(envc * sizeof(uint32_t)), sizeof(envp)) < 0) break;
            if (!envp) break;
            if (strncpy_from_user(&t->cpu_ctx, env_storage[envc], envp, sizeof(env_storage[envc])) < 0) break;
            env_local[envc] = env_storage[envc];
        }
    }
    env_local[envc] = NULL;

    const char *argv0 = (argc > 0) ? argv_local[0] : NULL;
    return k_exec_dispatch_path(path, argv0, argv_local, env_local);
}
static long sys_getcwd_impl(uint32_t buf_u, uint32_t sz, uint32_t, uint32_t, uint32_t, uint32_t) {
    struct task_struct *t = current; if (!t) return -EINTR;
    char cwd[500];
    int rc = vfs_getcwd_path(cwd, sizeof(cwd));
    if (rc < 0) return rc;
    if (sz == 0) return -EINVAL;
    size_t need = strlen(cwd) + 1u;
    if (need > sz) return -ERANGE;
    return copy_to_user(&t->cpu_ctx, buf_u, cwd, (uint32_t)need);
}
