extern "C" int _open_r(struct _reent *r, const char *path, int flags, int mode) {
    struct file *f = vfs_open(path, (uint32_t)flags, (uint16_t)mode);
    if (!f) { newlib_set_errno(r, errno ? errno : ENOENT); return -1; }
    struct task_struct *t = k_current_task();
    int fd = fd_alloc(t);
    if (fd < 0) { file_put(f); newlib_set_errno(r, -fd); return -1; }
    t->fd_table[fd] = f;
    return fd;
}

