extern "C" ssize_t _pread_r(struct _reent *r, int fd, void *buf, size_t n, off_t off) {
    struct task_struct *t = k_current_task();
    if (!t) { newlib_set_errno(r, EINTR); return -1; }
    struct file *f = k_fd_file(t, fd);
    if (!f || !f->f_ops || !f->f_ops->read) { newlib_set_errno(r, EBADF); return -1; }
    off_t save = f->pos;
    off_t tmp = off;
    ssize_t rc = f->f_ops->read(f, (char *)buf, n, &tmp);
    if (rc >= 0) {
        f->pos = save;
    }
    return rc;
}

extern "C" ssize_t _pwrite_r(struct _reent *r, int fd, const void *buf, size_t n, off_t off) {
    struct task_struct *t = k_current_task();
    if (!t) { newlib_set_errno(r, EINTR); return -1; }
    struct file *f = k_fd_file(t, fd);
    if (!f || !f->f_ops || !f->f_ops->write) { newlib_set_errno(r, EBADF); return -1; }
    off_t save = f->pos;
    off_t tmp = off;
    ssize_t rc = f->f_ops->write(f, (const char *)buf, n, &tmp);
    if (rc >= 0) {
        f->pos = save;
    }
    return rc;
}

extern "C" ssize_t _pread(int fd, void *buf, size_t n, off_t off) {
    return _pread_r(NULL, fd, buf, n, off);
}

extern "C" ssize_t _pwrite(int fd, const void *buf, size_t n, off_t off) {
    return _pwrite_r(NULL, fd, buf, n, off);
}

