#if 0 //UNUSED
static int prime_msb(const byte *p)
{
	int i;
	byte x;
	int shift = 1;
	int z     = F25519_SIZE - 1;

	/*
	    Test for any hot bits.
	    As soon as one instance is encountered set shift to 0.
	 */
	for (i = F25519_SIZE - 1; i >= 0; i--) {
		shift &= ((shift ^ ((-p[i] | p[i]) >> 7)) & 1);
		z -= shift;
	}
	x = p[z];
	z <<= 3;
	shift = 1;
	for (i = 0; i < 8; i++) {
		shift &= ((-(x >> i) | (x >> i)) >> (7 - i) & 1);
		z += shift;
	}

	return z - 1;
}
#endif

