	const char *g_progname;
	int g_lineno;
	int num_fields;             /* number of existing $N's */
	unsigned num_alloc_fields;  /* current size of Fields[] */
	/* NB: Fields[0] corresponds to $1, not to $0 */
	var *Fields;
	char *g_pos;
	char g_saved_ch;
	smallint got_program;
	smallint icase;
	smallint exiting;
	smallint nextrec;
