/* ===== BEGIN busybox-1.37.0/klibc-utils/nuke.c ===== */
/*
 * Copyright (c) 2017 Denys Vlasenko <vda.linux@googlemail.com>
 *
 * Licensed under GPLv2, see file LICENSE in this source tree.
 */
//config:config NUKE
//config:	bool "nuke (2.9 kb)"
//config:	default n  # off by default: too "accidentally destructive"
//config:	help
//config:	Alias to "rm -rf".

//applet:IF_NUKE(APPLET_NOEXEC(nuke, nuke, BB_DIR_BIN, BB_SUID_DROP, nuke))

