	"Indexed_directory" "\0"
	"No_Tailmerging" "\0"
	"Top_of_Directory_Hierarchies" "\0"
	"Extents" "\0"
	"No_COW" "\0"
	"Casefold" "\0"
	"Inline_Data" "\0"
	"Project_Hierarchy" "\0"
	"Verity" "\0"
	/* Another trailing NUL is added by compiler */;

void print_e2flags_long(unsigned flags)
{
	const uint32_t *fv;
	const char *fn;
	int first = 1;

	fv = e2attr_flags_value;
	fn = e2attr_flags_lname;
	do {
		if (flags & *fv) {
			if (!first)
				fputs(", ", stdout);
			fputs(fn, stdout);
			first = 0;
		}
		fv++;
		fn += strlen(fn) + 1;
	} while (*fn);
	if (first)
		fputs("---", stdout);
}

void print_e2flags(unsigned flags)
{
	const uint32_t *fv;
	const char *fn;

	fv = e2attr_flags_value;
	fn = e2attr_flags_sname;
	do  {
		char c = '-';
		if (flags & *fv)
			c = *fn;
		putchar(c);
		fv++;
		fn++;
	} while (*fn);
}

/* ===== END busybox-1.37.0/e2fsprogs/e2fs_lib.c ===== */

