#include "libbb.h"
#include "liblzo.h"

#define D_BITS          15
#define D_INDEX1(d,p)   d = DM(DMUL(0x21,DX3(p,5,5,6)) >> 5)
#define D_INDEX2(d,p)   d = (d & (D_MASK & 0x7ff)) ^ (D_HIGH | 0x1f)

#define DO_COMPRESS     lzo1x_1_15_compress

