/* --- local_t: per-CPU style counter model --- */
typedef struct { atomic_long a; } local_t;
#define LOCAL_INIT(v)               { .a = (atomic_long)((long)(v)) }
static inline long local_read(const local_t *l) { return l ? atomic_load_explicit(&l->a, memory_order_relaxed) : 0L; }
static inline void local_set(local_t *l, long v) { if (l) atomic_store_explicit(&l->a, v, memory_order_relaxed); }
static inline void local_add(long v, local_t *l) { if (l) (void)atomic_fetch_add_explicit(&l->a, v, memory_order_relaxed); }
static inline void local_sub(long v, local_t *l) { if (l) (void)atomic_fetch_sub_explicit(&l->a, v, memory_order_relaxed); }
static inline void local_inc(local_t *l) { local_add(1L, l); }
static inline void local_dec(local_t *l) { local_sub(1L, l); }
static inline long local_add_return(long v, local_t *l) { return l ? (atomic_fetch_add_explicit(&l->a, v, memory_order_relaxed) + v) : v; }
static inline long local_sub_return(long v, local_t *l) { return l ? (atomic_fetch_sub_explicit(&l->a, v, memory_order_relaxed) - v) : -v; }

